using System;
using System.Collections.Generic;
using System.IO;
using System.Text;
using System.Web.Script.Serialization;
using WoWProbe;

class FeedbackSummaryTests
{
    static int passed,failed;static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=16*1024*1024};
    static readonly Encoding Utf8=new UTF8Encoding(false);static readonly List<string> roots=new List<string>();
    static void Assert(bool ok,string message){if(!ok)throw new Exception(message);}static void Test(string name,Action action){try{action();passed++;Console.WriteLine("PASS "+name);}catch(Exception ex){failed++;Console.WriteLine("FAIL "+name+": "+ex.Message);}}
    static void Reject(Action action){try{action();}catch(FormatException){return;}catch(InvalidOperationException){return;}catch(IOException){return;}throw new Exception("invalid feedback was accepted");}
    static Dictionary<string,object> Read(string path){return (Dictionary<string,object>)Json.DeserializeObject(File.ReadAllText(path,Utf8));}static void Write(string path,object value){File.WriteAllText(path,Json.Serialize(value),Utf8);}
    static string Fixture(bool modern=false,bool live=false,int records=1)
    {
        string root=Path.Combine(Path.GetTempPath(),"wow-feedback-tests-"+Guid.NewGuid().ToString("N"));roots.Add(root);Directory.CreateDirectory(root);
        using(var journal=new RunJournal(Path.Combine(root,"private-runtime"),!live))
        {for(int i=0;i<records;i++)journal.Record("Stopped","reason-"+i,new OperationObservation(),new OperationCommand{Action=OperationAction.Key,Purpose=OperationPurpose.Travel,Key=0x57,HoldMilliseconds=120,Reason="planned only"},i*1000);journal.Export(root);}
        var manifest=Read(Path.Combine(root,"runtime-evidence.json"));var report=new Dictionary<string,object>{{"tool_version",modern?"0.6.0":"0.5.0"},{"game_validation","pending"},{"source",live?"live_attempt":"offline_simulation"},{"created_at",DateTimeOffset.UtcNow.ToString("o")},{"plan_fingerprint",new string('a',64)},{"wall_elapsed_ms",4000L},{"input_fault",false},{"events",new[]{"OLD RUN: should never become the current stop reason"}}};
        report["simulation"]=live?null:new Dictionary<string,object>{{"completed",false},{"status","Stopped"},{"reason","Current terminal reason"},{"virtual_elapsed_ms",9000L},{"native_input_events",0}};
        report["live"]=!live?null:new Dictionary<string,object>{{"status","Stopped"},{"engine","Vendor/AwaitSale"},{"reason","Current live terminal reason"},{"native_input_events",null}};
        if(modern){report["schema_version"]=1;report["run_id"]=manifest["run_id"];report["client_version"]="3.3.5";}
        Write(Path.Combine(root,"campaign-report.json"),report);return root;
    }
    static string Log(string root){var m=Read(Path.Combine(root,"runtime-evidence.json"));foreach(object name in (object[])m["files"])if(((string)name).EndsWith(".jsonl",StringComparison.Ordinal))return Path.Combine(root,(string)name);throw new Exception("fixture log missing");}
    static void MutateLog(string root,string kind,Action<Dictionary<string,object>> change)
    {
        string path=Log(root);var lines=File.ReadAllLines(path,Utf8);bool changed=false;for(int i=0;i<lines.Length;i++){var row=(Dictionary<string,object>)Json.DeserializeObject(lines[i]);if((string)row["kind"]!=kind)continue;change(row);lines[i]=Json.Serialize(row);changed=true;}Assert(changed,"fixture log row missing");File.WriteAllLines(path,lines,Utf8);
    }
    static bool Warn(FeedbackSummary s,string fragment){foreach(string w in s.Warnings)if(w.IndexOf(fragment,StringComparison.Ordinal)>=0)return true;return false;}
    static int Main()
    {
        Test("legacy simulation stays pending and warns about weak report association",delegate{var root=Fixture();var s=FeedbackSummary.Load(root);Assert(s.Source=="offline_simulation"&&s.ToolVersion=="0.5.0"&&s.GameValidation=="pending","source/version changed");Assert(s.StopReason=="Current terminal reason"&&s.LastState=="Stopped","mixed old events replaced current cause");Assert(s.VirtualMilliseconds==9000&&s.WallMilliseconds==4000&&s.ClientVersion=="未知","times or unknown client lost");Assert(Warn(s,"旧")&&s.RunId.Length==32,"legacy association not explained");});
        Test("modern report links matching run and client metadata",delegate{var s=FeedbackSummary.Load(Fixture(true));Assert(s.ClientVersion=="3.3.5"&&s.RunId.Length==32&&!Warn(s,"旧版报告"),"modern metadata absent");});
        Test("live attempt never borrows virtual duration or treats planned input as executed",delegate{var s=FeedbackSummary.Load(Fixture(true,true));var md=s.ToMarkdown();Assert(s.Source=="live_attempt"&&s.GameValidation=="pending"&&s.VirtualMilliseconds==-1,"live got a fabricated virtual duration");Assert(md.IndexOf("实机尝试",StringComparison.Ordinal)>=0&&md.IndexOf("计划",StringComparison.Ordinal)>=0,"provenance missing");});
        Test("last twenty current-run log events are kept and wide observations parse",delegate{var s=FeedbackSummary.Load(Fixture(true,false,30));Assert(s.RecentEvents.Count==20&&s.RecentEvents[0].IndexOf("reason-10",StringComparison.Ordinal)>=0&&s.RecentEvents[19].IndexOf("reason-29",StringComparison.Ordinal)>=0,"event bound/order incorrect");});
        Test("claimed passed game validation cannot become verified acceptance",delegate{var root=Fixture(true);var p=Path.Combine(root,"campaign-report.json");var r=Read(p);r["game_validation"]="passed";Write(p,r);var s=FeedbackSummary.Load(root);Assert(s.GameValidation=="pending"&&Warn(s,"验收"),"import trusted claimed pass");});
        Test("duplicate report keys and contradictory source branches are rejected",delegate{var root=Fixture(true);var p=Path.Combine(root,"campaign-report.json");File.WriteAllText(p,File.ReadAllText(p).Replace("\"source\":\"offline_simulation\"","\"source\":\"offline_simulation\",\"source\":\"live_attempt\""),Utf8);Reject(delegate{FeedbackSummary.Load(root);});root=Fixture(true);p=Path.Combine(root,"campaign-report.json");var r=Read(p);r["source"]="live_attempt";Write(p,r);Reject(delegate{FeedbackSummary.Load(root);});});
        Test("report manifest and log identity contradictions are rejected",delegate{var root=Fixture(true);var p=Path.Combine(root,"campaign-report.json");var r=Read(p);r["run_id"]=new string('b',32);Write(p,r);Reject(delegate{FeedbackSummary.Load(root);});root=Fixture(true);p=Path.Combine(root,"runtime-evidence.json");r=Read(p);r["source"]="live_observation";Write(p,r);Reject(delegate{FeedbackSummary.Load(root);});root=Fixture(true);p=Log(root);File.WriteAllText(p,File.ReadAllText(p).Replace("\"source\":\"simulation\"","\"source\":\"live_observation\""),Utf8);Reject(delegate{FeedbackSummary.Load(root);});});
        Test("simulation headers and observations cannot claim actual native input",delegate{foreach(string kind in new[]{"wowprobe_runtime_log","observation"}){var root=Fixture(true);MutateLog(root,kind,delegate(Dictionary<string,object> row){row["native_input_events"]=1;});Reject(delegate{FeedbackSummary.Load(root);});}});
        Test("simulation native input counts must be nonnegative integers",delegate{foreach(object count in new object[]{"0",-1,true}){var root=Fixture(true);MutateLog(root,"observation",delegate(Dictionary<string,object> row){row["native_input_events"]=count;});Reject(delegate{FeedbackSummary.Load(root);});}});
        Test("missing legacy log input counts remain unknown with a warning",delegate{foreach(string kind in new[]{"wowprobe_runtime_log","observation"}){var root=Fixture();MutateLog(root,kind,delegate(Dictionary<string,object> row){row.Remove("native_input_events");});var s=FeedbackSummary.Load(root);Assert(s.GameValidation=="pending"&&Warn(s,"native_input_events"),"missing input count was treated as known zero");}});
        Test("manifest paths cannot escape use devices or mix another run",delegate{foreach(string bad in new[]{"../outside.jsonl","C:\\outside.jsonl","sub/log.jsonl","CON.jsonl","run-20260101-010101000-"+new string('b',32)+"-000001.jsonl"}){var root=Fixture(true);var p=Path.Combine(root,"runtime-evidence.json");var m=Read(p);m["files"]=new[]{bad};Write(p,m);Reject(delegate{FeedbackSummary.Load(root);});}});
        Test("case-colliding duplicate manifest files are rejected",delegate{var root=Fixture(true);var p=Path.Combine(root,"runtime-evidence.json");var m=Read(p);string name=Path.GetFileName(Log(root));m["files"]=new[]{name,name.ToUpperInvariant()};Write(p,m);Reject(delegate{FeedbackSummary.Load(root);});});
        Test("missing optional manifest or log is a visible warning",delegate{var root=Fixture(true);File.Delete(Log(root));var s=FeedbackSummary.Load(root);Assert(Warn(s,"缺失"),"missing log was silent");File.Delete(Path.Combine(root,"runtime-evidence.json"));s=FeedbackSummary.Load(root);Assert(Warn(s,"清单"),"missing manifest was silent");});
        Test("incomplete final log line warns while duplicate closed JSON fails",delegate{var root=Fixture(true);File.AppendAllText(Log(root),"{\"kind\":\"observation\",",Utf8);var s=FeedbackSummary.Load(root);Assert(Warn(s,"截断"),"incomplete tail not marked");root=Fixture(true);File.AppendAllText(Log(root),"{\"kind\":\"observation\",\"kind\":\"observation\"}",Utf8);Reject(delegate{FeedbackSummary.Load(root);});});
        Test("oversized reports and manifests are rejected before parsing",delegate{var root=Fixture(true);using(var f=new FileStream(Path.Combine(root,"campaign-report.json"),FileMode.Open,FileAccess.Write))f.SetLength(8L*1024*1024+1);Reject(delegate{FeedbackSummary.Load(root);});root=Fixture(true);using(var f=new FileStream(Path.Combine(root,"runtime-evidence.json"),FileMode.Open,FileAccess.Write))f.SetLength(4L*1024*1024+1);Reject(delegate{FeedbackSummary.Load(root);});});
        Test("oversized optional logs produce a bounded incomplete-analysis warning",delegate{var root=Fixture(true);using(var f=new FileStream(Log(root),FileMode.Open,FileAccess.Write))f.SetLength(10L*1024*1024+1);var s=FeedbackSummary.Load(root);Assert(Warn(s,"上限"),"oversize optional log did not warn");});
        Test("unlisted neighboring files are not read",delegate{var root=Fixture(true);File.WriteAllBytes(Path.Combine(root,"unrelated.jsonl"),new byte[]{255,254,0});var s=FeedbackSummary.Load(root);Assert(s.StopReason=="Current terminal reason","unrelated file affected current feedback");});
        Test("Markdown escapes user fields and removes control characters",delegate{var root=Fixture(true);var p=Path.Combine(root,"campaign-report.json");var r=Read(p);r["client_version"]="[bad](https://example.invalid)\u0000";var sim=(Dictionary<string,object>)r["simulation"];sim["reason"]="`code`\n# injected | <tag>";Write(p,r);var md=FeedbackSummary.Load(root).ToMarkdown();Assert(md.IndexOf("[bad](",StringComparison.Ordinal)<0&&md.IndexOf("\n# injected",StringComparison.Ordinal)<0&&md.IndexOf('\0')<0&&md.IndexOf("<tag>",StringComparison.Ordinal)<0,"unsafe Markdown preserved");});
        Test("reading and rendering do not alter source files",delegate{var root=Fixture(true);var paths=Directory.GetFiles(root,"*",SearchOption.TopDirectoryOnly);var bytes=new Dictionary<string,string>();foreach(string p in paths)bytes[p]=Convert.ToBase64String(File.ReadAllBytes(p));var s=FeedbackSummary.Load(root);s.ToMarkdown();foreach(string p in paths)Assert(bytes[p]==Convert.ToBase64String(File.ReadAllBytes(p)),"feedback source changed");});
        Test("multibyte log lines enforce bytes even below character limit",delegate{var root=Fixture(true);var m=Read(Path.Combine(root,"runtime-evidence.json"));var row=new{kind="observation",schema_version=1,run_id=m["run_id"],source="simulation",game_validation="pending",state="Stopped",reason=new string('怪',23000),command=(object)null};File.AppendAllText(Log(root),Json.Serialize(row)+"\n",Utf8);Reject(delegate{FeedbackSummary.Load(root);});});
        Test("invalid UTF8 in optional logs is rejected explicitly",delegate{var root=Fixture(true);using(var f=new FileStream(Log(root),FileMode.Append,FileAccess.Write))f.WriteByte(255);Reject(delegate{FeedbackSummary.Load(root);});});
        Test("only sixty four declared logs are analyzed",delegate{var root=Fixture(true);var path=Path.Combine(root,"runtime-evidence.json");var m=Read(path);var names=new List<string>();for(int i=0;i<65;i++){string name="run-20260101-010101000-"+m["run_id"]+"-"+(i+1).ToString("D6")+".jsonl";names.Add(name);Write(Path.Combine(root,name),new{kind="wowprobe_runtime_log",schema_version=1,run_id=m["run_id"],source=i==64?"live_observation":"simulation",game_validation="pending"});}m["files"]=names;Write(path,m);var s=FeedbackSummary.Load(root);Assert(Warn(s,"64"),"unbounded log count or missing partial-analysis warning");});
        Test("whitespace-only log separators do not become malformed observations",delegate{var root=Fixture(true);File.AppendAllText(Log(root)," \r\n\t\n",Utf8);Assert(FeedbackSummary.Load(root).RecentEvents.Count==1,"whitespace created evidence");});
        Test("UTF16 log substitution is not silently treated as UTF8 evidence",delegate{var root=Fixture(true);string p=Log(root),body=File.ReadAllText(p,Utf8);File.WriteAllText(p,body,Encoding.Unicode);Reject(delegate{FeedbackSummary.Load(root);});});
        Test("total log bytes stop at sixty four MiB without reading the tail",delegate{var root=Fixture(true);var path=Path.Combine(root,"runtime-evidence.json");var m=Read(path);var names=new List<string>();byte[] blank=new byte[1024];for(int i=0;i<blank.Length-1;i++)blank[i]=32;blank[blank.Length-1]=10;for(int i=0;i<7;i++){string name="run-20260101-010101000-"+m["run_id"]+"-"+(i+1).ToString("D6")+".jsonl";names.Add(name);using(var f=new FileStream(Path.Combine(root,name),FileMode.Create,FileAccess.Write)){byte[] header=Utf8.GetBytes(Json.Serialize(new{kind="wowprobe_runtime_log",schema_version=1,run_id=m["run_id"],source="simulation",game_validation="pending"})+"\n");f.Write(header,0,header.Length);long goal=10L*1024*1024;while(f.Position+blank.Length<=goal)f.Write(blank,0,blank.Length);while(f.Position<goal)f.WriteByte(10);}}m["files"]=names;Write(path,m);var summary=FeedbackSummary.Load(root);Assert(Warn(summary,"64MiB"),"total byte budget not reported");});
        foreach(string root in roots){string full=Path.GetFullPath(root),parent=Path.GetDirectoryName(full).TrimEnd(Path.DirectorySeparatorChar);if(parent==Path.GetFullPath(Path.GetTempPath()).TrimEnd(Path.DirectorySeparatorChar)&&Path.GetFileName(full).StartsWith("wow-feedback-tests-",StringComparison.Ordinal))Directory.Delete(full,true);}
        Console.WriteLine("Feedback summary tests: "+passed+" passed, "+failed+" failed. Read-only files; no input backend.");return failed==0?0:1;
    }
}
